    (false, true) => {
        let mut fallback_router = other_fallback;
        panic_on_err!(fallback_router.merge(self.fallback_router));
        (fallback_router, false)
    }
    // both have a custom fallback, not allowed
    (false, false) => {
        panic!("Cannot merge two `Router`s that both have a fallback")
    }
};

