pub(super) fn merge_fallback(
    &mut self,
    other: PathRouter<S, IS_FALLBACK>,
) -> Result<(), Cow<'static, str>> {
    let PathRouter {
        routes,
        node,
        prev_route_id: _,
    } = other;

    for (id, endpoint) in routes {
        let path = node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue")
            .clone();

        if let Some(existing_id) = self.node.path_to_route_id.get(&path).copied() {
            self.routes.insert(existing_id, endpoint);
        } else {
            let id = self.next_route_id();
            self.set_node(&path, id)?;
            self.routes.insert(id, endpoint);
        }
    }

    Ok(())
}

