pub fn merge<R>(mut self, other: R) -> Self
where
    R: Into<Router<S>>,
{
    let Router {
        path_router,
        fallback_router: other_fallback,
        default_fallback,
        catch_all_fallback,
    } = other.into();

    panic_on_err!(self.path_router.merge(path_router));

    let (fallback_router, default_fallback) = match (self.default_fallback, default_fallback) {
        // both have the default fallback
        // merge the routers so fallbacks from nested routers are preserved
        (true, true) => {
            let mut fallback_router = self.fallback_router;
            panic_on_err!(fallback_router.merge(other_fallback));
            (fallback_router, true)
        }
        // self has default fallback, other has a custom fallback
        // merge the routers so fallbacks from nested routers are preserved
        (true, false) => {
            let mut fallback_router = self.fallback_router;
            panic_on_err!(fallback_router.merge(other_fallback));
            (fallback_router, false)
        }
        // self has a custom fallback, other has a default
        // merge the routers so fallbacks from nested routers are preserved
        (false, true) => {
            let mut fallback_router = other_fallback;
            panic_on_err!(fallback_router.merge(self.fallback_router));
            (fallback_router, false)
        }
        // both have a custom fallback, not allowed
        (false, false) => {
            panic!("Cannot merge two `Router`s that both have a fallback")
        }
    };

    self.fallback_router = fallback_router;
    self.default_fallback = default_fallback;

    self.catch_all_fallback = self
        .catch_all_fallback
        .merge(catch_all_fallback)
        .unwrap_or_else(|| panic!("Cannot merge two `Router`s that both have a fallback"));

    self
}

